private static String prettyPrint(byte[] data) {
  final int dataLength = data.length;
  if (dataLength == 0) {
    return "";
  }
  StringBuilder sb = new StringBuilder(dataLength + 16);
  for (int i = 0; i < dataLength; i++) {
    byte c = data[i];
    if (c >= 32 && c < 127) {
      sb.append((char) c);
    } else {
      sb.append("\\x");
      sb.append(String.format(Locale.ENGLISH, "%02x", c));
    }
  }
  return sb.toString();
}

