{
    CK_ARGUMENT_POTENTIALLY_UNUSED(timeout);

    jux_sockaddr_t *addr = (*env)->GetDirectBufferAddress(env, ab);
    socklen_t suLength = (socklen_t)abLen;

    int serverHandle = _getFD(env, fdServer);
    if(serverHandle < 0) {
