import org.newsclub.net.unix.AFUNIXServerSocket;
import org.newsclub.net.unix.AFUNIXSocket;
import org.newsclub.net.unix.AFUNIXSocketAddress;

public class JavaConnTest {
  public static void main(String[] args) throws Exception {
    String[] names = args.length > 0 ? args : new String[]{"foobar", "abc", "a b", "@special"};
    for (String name : names) {
      AFUNIXSocketAddress addr = AFUNIXSocketAddress.inAbstractNamespace(name);
      AFUNIXServerSocket server = AFUNIXServerSocket.newInstance();
      server.bind(addr);
      System.out.println("[server] bound to abstract '" + name + "' local=" + server.getLocalSocketAddress());
      System.out.println("[server] local bytes=" + java.util.Arrays.toString(server.getLocalSocketAddress().getPathAsBytes()));

      Thread t = new Thread(() -> {
        try {
          AFUNIXSocket accepted = server.accept();
          System.out.println("[server] accepted local=" + accepted.getLocalSocketAddress());
          System.out.println("[server] accepted remote=" + accepted.getRemoteSocketAddress());
          byte[] b = accepted.getRemoteSocketAddress().getPathAsBytes();
          System.out.println("[server] accepted remote bytes=" + java.util.Arrays.toString(b));
          accepted.close();
        } catch (Exception e) {
          e.printStackTrace();
        }
      });
      t.start();

      AFUNIXSocket client = AFUNIXSocket.newInstance();
      client.connect(addr);
      System.out.println("[client] connected to abstract '" + name + "' local=" + client.getLocalSocketAddress());
      System.out.println("[client] remote=" + client.getRemoteSocketAddress());
      client.close();
      t.join();
      server.close();
      System.out.println("[server] closed\n");
    }
  }
}
